import { TagGroup, type TagGroupRemoveDetail } from '@absoluteui/components/tag-group';

const host = document.createElement('div');
const status = document.createElement('p');
document.body.append(host, status);
const filters = TagGroup.create(host, {
  label: 'Applied filters',
  removable: true,
  items: [
    { value: 'london', label: 'Location: London' },
    { value: 'remote', label: 'Remote' },
    { value: 'senior', label: 'Level: Senior' },
  ],
});
host.addEventListener('aui-remove', (event) => {
  const { item } = (event as CustomEvent<TagGroupRemoveDetail>).detail;
  status.textContent = `${String(filters.items.length - 1)} filters applied (removed ${item.label})`;
});

import { TagGroup, type TagGroupChangeDetail } from '@absoluteui/components/tag-group';

const host = document.createElement('div');
const result = document.createElement('p');
document.body.append(host, result);
TagGroup.create(host, {
  label: 'Categories',
  selection: 'multiple',
  value: ['design'],
  items: [
    { value: 'design', label: 'Design' },
    { value: 'engineering', label: 'Engineering' },
    { value: 'sales', label: 'Sales' },
    { value: 'legal', label: 'Legal', disabled: true },
  ],
});
host.addEventListener('aui-change', (event) => {
  result.textContent = `Showing: ${(event as CustomEvent<TagGroupChangeDetail>).detail.value.join(', ') || 'all'}`;
});
